import os
import torch
import random
import numpy as np


class Config:
    # --- Reproducibility ---
    SEED = 42

    # --- Paths ---
    INPUT_DIR = "./input"
    METADATA_DIR = "./metadata"

    # Metadata files generated by the provided script
    TRAIN_METADATA = os.path.join(METADATA_DIR, "train.csv")
    VAL_METADATA = os.path.join(METADATA_DIR, "val.csv")
    TEST_METADATA = os.path.join(METADATA_DIR, "test.csv")

    # Output directories
    WORKING_DIR = "./working/idea_3"
    SUBMISSION_DIR = "./submission"
    SUBMISSION_PATH = os.path.join(SUBMISSION_DIR, "submission.csv")
    MODEL_PATH = os.path.join(WORKING_DIR, "best_model.pth")

    # --- Data Preprocessing ---
    # Resizing spatial dimensions to (256, 256) as per Idea 3
    IMG_SIZE = 256
    # The cadence depth (ABACAD)
    NUM_FRAMES = 6

    # --- Model Hyperparameters ---
    # 2D CNN specific settings (Cite solution_lesson_node_00008)
    IN_CHANNELS = 6  # Input is (Batch, 6, Height, Width)

    # --- Training Hyperparameters ---
    BATCH_SIZE = 32
    EPOCHS = 20
    LEARNING_RATE = 1e-3
    WEIGHT_DECAY = 1e-2

    # Mixup augmentation parameter
    MIXUP_ALPHA = 0.2

    # Early Stopping
    PATIENCE = 5

    # --- Compute ---
    DEVICE = "cuda" if torch.cuda.is_available() else "cpu"
    NUM_WORKERS = 4  # 12 vCPUs available

    # --- Debugging ---
    # Set to True to train on a small subset for quick pipeline checks
    DEBUG = False
    DEBUG_SAMPLE_SIZE = 2000

    @classmethod
    def setup(cls):
        """
        Ensures necessary directories exist and sets random seeds.
        """
        os.makedirs(cls.WORKING_DIR, exist_ok=True)
        os.makedirs(cls.SUBMISSION_DIR, exist_ok=True)

        # Set reproducible seeds
        random.seed(cls.SEED)
        np.random.seed(cls.SEED)
        torch.manual_seed(cls.SEED)
        if torch.cuda.is_available():
            torch.cuda.manual_seed_all(cls.SEED)
            torch.backends.cudnn.deterministic = True
            torch.backends.cudnn.benchmark = False
